sql:
SELECT vacants, parc_prive, ROUND((vacants::numeric / parc_prive) * 100, 1) AS vacancy_rate_percent
FROM dvf.logements_vacants
WHERE code = '33063' AND niveau = 'commune' AND annee = 2025;

